/**
 * Planner — editable application source
 * Storage key: planner_app_v1
 * Modes: browser localStorage or Python/SQLite server (server.py).
 * Edit DEFAULT to change starter goals; edit render* to change UI.
 */
(()=>{'use strict';
document.addEventListener('submit',e=>{if(e.target.tagName==='FORM')e.preventDefault()},true);
const STORE='planner_app_v1';const DEFAULT={version:1,weeklyGoals:{},weeklyStats:{},daily:{},goals:[],educationChoice:'exploring',jobStatus:'searching',notes:{career:'',education:'',monthly:''},finance:{weddingGoal:'',weddingSaved:'',weddingMonthly:'',educationGoal:'',educationSaved:'',educationMonthly:''},monthReviews:{},yearReviews:{}};
function weeklyItems(){return (state.weeklyItems||[]).map(([id,title,desc])=>[id,esc(title),esc(desc)])}
const nav=[['overview','◫','Overview'],['daily','☑','Daily routine'],['schedule','▦','My schedule'],['weekly','▥','Weekly tracker'],['goals','◇','Goals & tasks'],['reviews','◷','Progress & reviews'],['finance','◈','Savings planner'],['data','▤','Data explorer'],['settings','⚙','Settings & backup']];
let state=load();let page=nav.some(x=>x[0]===location.hash?.slice(1))?location.hash.slice(1):'overview';let dbMode=false;let dbUpdated='';let syncQueue=null;let syncing=false;let dataDataset='goals';let dataFilter='';let day=iso(new Date());let reviewMonth=day.slice(0,7);let reviewYear=Number(day.slice(0,4));
function clone(x){return JSON.parse(JSON.stringify(x))}function load(){try{const raw=localStorage.getItem(STORE);if(!raw)return clone(DEFAULT);const s=JSON.parse(raw);if(!s||typeof s!=='object'||!s.weeklyGoals)return clone(DEFAULT);return {...clone(DEFAULT),...s,notes:{...DEFAULT.notes,...(s.notes||{})},finance:{...DEFAULT.finance,...(s.finance||{})},monthReviews:s.monthReviews||{},yearReviews:s.yearReviews||{}}}catch(e){return clone(DEFAULT)}}function save(){
 let message='Saved in browser ✓';
 try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){message='Browser storage failed: export a JSON backup'}
 const el=document.querySelector('#page-'+page+' #saveState');if(el)el.textContent=message;
 if(dbMode)enqueueDbSave();
}
async function boot(){
 // Open index.html directly for browser-only mode; use localhost via server.py for real SQLite mode.
 if(location.protocol==='http:'&&(location.hostname==='127.0.0.1'||location.hostname==='localhost')){
   try{
     const r=await fetch('/api/state',{cache:'no-store'});
     if(r.ok){const result=await r.json();dbMode=true;dbUpdated=result.updatedAt||'';
       if(result.state&&result.state.version===1){state={...clone(DEFAULT),...result.state};try{localStorage.setItem(STORE,JSON.stringify(state))}catch(_){}}
       else if(localStorage.getItem(STORE)){enqueueDbSave()}
     }
   }catch(error){console.warn('SQLite unavailable; using browser storage',error)}
 }
 if(ensureDiaryEntries())save();
 if(location.hash==='#future'){page='goals';history.replaceState(null,'',location.pathname+'#goals')}
 render();
}
function enqueueDbSave(){
 syncQueue=JSON.stringify(state);if(!syncing)flushDbSaves();
}
async function flushDbSaves(){
 syncing=true;
 while(syncQueue!==null){
   const snapshot=syncQueue;syncQueue=null;
   try{
     const response=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:snapshot});
     if(!response.ok)throw new Error('HTTP '+response.status);
     const result=await response.json();dbUpdated=result.updatedAt||'';
     const el=document.querySelector('#page-'+page+' #saveState');if(el)el.textContent='Saved to SQLite ✓';
   }catch(error){
     console.error('SQLite save failure:',error);
     const el=document.querySelector('#page-'+page+' #saveState');if(el)el.textContent='SQLite save failed — export a backup!';
   }
 }
 syncing=false;
 if(page==='data')renderData();
}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function parseDate(str){let v=String(str).split('-').map(Number);return new Date(v[0],v[1]-1,v[2])}function daysLeft(target){const n=new Date();n.setHours(0,0,0,0);return Math.max(0,Math.ceil((parseDate(target)-n)/86400000))}function monthsLeft(target){return Math.max(1,Math.ceil(daysLeft(target)/30.44))}function thisWeek(date=new Date()){let d=new Date(date.getFullYear(),date.getMonth(),date.getDate());d.setDate(d.getDate()-(d.getDay()+6)%7);return iso(d)}function curStats(){return state.weeklyStats[thisWeek()]||{}}function statsFor(key){return state.weeklyStats[key]||(state.weeklyStats[key]={})}function count(key){return Math.max(0,Number(curStats()[key]||0))}function target(key){return Math.max(1,Number(state.weeklyGoals[key]||1))}function progress(){let sum=0;for(const [key] of weeklyItems())sum+=Math.min(1,count(key)/target(key));return Math.round(100*sum/(weeklyItems().length||1))}function dstate(){return state.daily[day]||(state.daily[day]={checks:{},note:''})}function field(k){return Number(state.finance[k])||0}function money(v){return 'RM '+Math.round(v).toLocaleString('en-MY')}function heading(k,title,subtitle){return `<header class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><div class="muted">${subtitle}</div></div><span id="saveState" class="tiny">Changes save automatically</span></header>`}function meter(p,c=''){return `<div class="progress ${c}"><i style="width:${Math.max(0,Math.min(100,p))}%"></i></div>`}function milestone(year,date,title,desc){return `<div class="milestone"><div class="date">${year}<span>${date}</span></div><div><strong>${title}</strong><p>${desc}</p></div></div>`}function cardMetric(label,value,foot){return `<div class="metric span3"><div class="cap">${label}</div><div class="value">${value}</div><div class="foot">${foot}</div></div>`}
function renderNav(){const markup=(mobile=false)=>nav.filter(x=>!mobile||['overview','daily','weekly','goals','schedule'].includes(x[0])).map(x=>`<button class="${page===x[0]?'active':''}" data-page="${x[0]}"><span class="${mobile?'':'symbol'}">${x[1]}</span>${x[2]}</button>`).join('');document.getElementById('desktopNav').innerHTML=markup(false);document.getElementById('mobileNav').innerHTML=markup(true);document.getElementById('mobileDropdown').innerHTML=markup(false);document.getElementById('sideProgress').style.width=progress()+'%';document.getElementById('sideProgressText').textContent=`This week's targets: ${progress()}%`}
function renderOverview(){document.getElementById('page-overview').innerHTML=heading('YOUR PERSONAL PLANNER','A life you are building','Small steps towards goals you chose.')+`<div class="grid"><div class="hero span12"><div><small>HELLO, ${esc(profile().name.toUpperCase())} ✦</small><h2>${esc(state.plan?.main||'Make space for what matters to you.')}</h2><p>Your pace. Your priorities. Your next chapter.</p></div></div>${cardMetric('DAILY HABITS',habits().length,'Your personal routine')}${cardMetric('WEEKLY PROGRESS',progress()+'%','Across your chosen targets')}${cardMetric('GOALS COMPLETED',state.goals.filter(g=>g.done).length,'Keep taking small steps')}${cardMetric('OPEN GOALS',state.goals.filter(g=>!g.done).length,'One meaningful action at a time')}<div class="panel span6"><h2>This month</h2><p>${esc(state.plan?.monthly||'Set your monthly direction in setup.')}</p><button class="action" data-page="reviews">Review my progress →</button></div><div class="panel span6"><h2>This year</h2><p>${esc(state.plan?.yearly||'Set your yearly direction in setup.')}</p><button class="action" data-page="goals">My goals →</button></div><div class="panel span12"><h2>This week, on your terms</h2>${weeklyItems().map(([k,title])=>`<div class="stat-line"><span>${title}</span><b>${count(k)} / ${target(k)}</b></div>${meter(100*count(k)/target(k))}`).join('')||'<p>Choose your daily habits in setup to create weekly targets.</p>'}<button class="action outline" data-page="weekly">Update week →</button></div></div>`}


function renderWeekly(){const monday=parseDate(thisWeek()),sunday=new Date(monday);sunday.setDate(sunday.getDate()+6);document.getElementById('page-weekly').innerHTML=heading('YOUR MOMENTUM','Weekly tracker','Count meaningful actions, not hours spent feeling busy.')+`<div class="grid"><div class="span12 hero" style="min-height:125px"><div><small>CURRENT WEEK</small><h2 style="margin-bottom:4px">${monday.toLocaleDateString('en-MY',{day:'numeric',month:'short'})} – ${sunday.toLocaleDateString('en-MY',{day:'numeric',month:'short',year:'numeric'})}</h2><p>Adjust your weekly goals under Settings if life gets busier.</p></div><div class="hero-badge">${progress()}% of targets</div></div><div class="panel span8"><h2>Action counters</h2><p class="tiny" style="margin-top:0">Use + when you complete an action and − to correct a count.</p>${weeklyItems().map(([key,name,desc])=>`<div class="weekstat"><div class="weekstat-main"><div style="font-weight:800;font-size:14px">${name}</div><div class="tiny">${desc}</div>${meter(Math.round(count(key)/target(key)*100),key==='rest'?'green':'')}</div><div class="counter"><button class="smallbtn" data-counter="${key}" data-n="-1" aria-label="Decrease ${name}">−</button><b>${count(key)}/${target(key)}</b><button class="smallbtn" data-counter="${key}" data-n="1" aria-label="Increase ${name}">+</button></div></div>`).join('')}<div class="row between wrap" style="margin-top:20px"><span class="pill green">${progress()}% of your weekly targets</span><button class="action outline" data-clearweek="1">Clear this week's counts</button></div></div><div class="panel span4"><h2>Your rhythm</h2><p class="muted">${esc(state.plan?.rhythm||'Choose a pace that feels achievable.')}</p><p>Weekly targets start from your daily habits. Adjust the number of sessions in Settings.</p><button class="action outline" data-setup="1">Edit my plan</button></div></div>`}
function goalYearGroups(goals){
 const groups=new Map();
 for(const goal of goals){const year=/^\d{4}-\d{2}-\d{2}$/.test(goal.due||'')?goal.due.slice(0,4):'No date set';if(!groups.has(year))groups.set(year,[]);groups.get(year).push(goal)}
 return [...groups.entries()].sort(([a],[b])=>a==='No date set'?1:b==='No date set'?-1:a.localeCompare(b)).map(([year,items])=>[year,items.slice().sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'').localeCompare(b.due||''))]);
}
function renderGoalGroups(){return goalYearGroups(state.goals).map(([year,goals])=>`<section class="goal-year-group"><div class="row between wrap goal-year-heading"><h3>${esc(year)}</h3><span class="tiny">${goals.filter(g=>g.done).length} / ${goals.length} completed</span></div><div class="list">${goals.map(g=>`<label class="goalrow ${g.done?'completed':''}"><input type="checkbox" data-goalcheck="${esc(g.id)}" ${g.done?'checked':''}><span class="grow"><strong>${esc(g.title)}</strong><small>${esc(g.area)} · ${g.due?`Target: ${esc(g.due)}`:'No date set'}</small></span><button type="button" class="goal-edit" data-goaledit="${esc(g.id)}" aria-label="Edit ${esc(g.title)}">Edit</button><button type="button" data-goaldelete="${esc(g.id)}" aria-label="Delete goal" title="Delete">×</button></label>`).join('')}</div></section>`).join('')||'<div class="callout">Nothing added yet. Start with one small goal.</div>'}
function renderGoals(){const done=state.goals.filter(x=>x.done).length;document.getElementById('page-goals').innerHTML=heading('YOUR NEXT ACTIONS','Goals & task board','Hold long-term aspirations while working on near-term actions.')+`<div class="grid"><div class="panel span8"><div class="row between panel-title"><div><h2>My goals</h2><div class="tiny">${done} out of ${state.goals.length} completed</div></div><span class="pill">${state.goals.length?Math.round(done/state.goals.length*100):0}% done</span></div>${meter(state.goals.length?done/state.goals.length*100:0,'green')}<div class="list" style="margin-top:18px">${renderGoalGroups()}</div></div><div class="panel span4"><h2>Add one goal</h2><p class="tiny">Small, specific tasks are easier to act on.</p><form id="newGoalForm" class="list"><div class="field"><label for="newGoalTitle">What do you want to do?</label><input id="newGoalTitle" maxlength="160" placeholder="e.g. Complete a study session" required></div><div class="field"><label for="newGoalArea">Area</label><select id="newGoalArea"><option>Career</option><option>Skills</option><option>Education</option><option>Finance</option><option>Personal</option></select></div><div class="field"><label for="newGoalDue">Target date (optional)</label><input id="newGoalDue" type="date"></div><button class="action" type="submit">+ Add goal</button></form><div class="rule"></div><div class="callout teal">Try adding a small goal you can complete in 7–14 days, rather than a long list of vague plans.</div></div></div>`}




function renderFinance(){const year=new Date().getFullYear();document.getElementById('page-finance').innerHTML=heading('PLAN AT YOUR PACE','Savings planner','Explore monthly savings towards your chosen amounts.')+`<div class="grid">${moneyCard('Savings fund 1','wedding',year+'-12-31')}${moneyCard('Savings fund 2','education',(year+1)+'-12-31')}</div>`}

// -------- READ-ONLY DATABASE EXPLORER & CSV EXPORT --------
function collectData(){
 const dailyEntries=Object.entries(state.daily||{});
 const weeklyEntries=Object.entries(state.weeklyStats||{});
 return {
 goals:(state.goals||[]).map(g=>({id:g.id,title:g.title,area:g.area,due:g.due,completed:Boolean(g.done)})),
 daily:dailyEntries.map(([date,x])=>({date,completedTasks:Object.values(x.checks||{}).filter(Boolean).length,note:x.note||''})),
 diary:dailyEntries.flatMap(([date,x])=>(x.diaryEntries||[]).map(entry=>({date,id:entry.id,text:entry.text,createdAt:entry.createdAt||'',updatedAt:entry.updatedAt||''}))),
 tasks:dailyEntries.flatMap(([date,d])=>(d.todos||[]).map(t=>({date,id:t.id,title:t.title,createdAt:t.createdAt,completed:Boolean(d.checks?.['todo_'+t.id])}))),
 checks:dailyEntries.flatMap(([date,x])=>Object.entries(x.checks||{}).map(([task,done])=>({date,task,completed:Boolean(done)}))),
 weekly:weeklyEntries.flatMap(([week,x])=>Object.entries(x).map(([category,value])=>({week,category,count:value,target:state.weeklyGoals[category]??''}))),
 targets:Object.entries(state.weeklyGoals||{}).map(([category,target])=>({category,target})),
 monthly:Object.entries(state.monthReviews||{}).map(([month,x])=>({month,focus:x.focus||'',wins:x.wins||'',adjust:x.adjust||''})),
 yearly:Object.entries(state.yearReviews||{}).map(([year,x])=>({year,focus:x.focus||'',success:x.success||'',reflection:x.reflection||''})),
 savings:['wedding','education'].map(category=>({category,target:state.finance[category+'Goal']||0,saved:state.finance[category+'Saved']||0,monthly:state.finance[category+'Monthly']||0})),
 notes:Object.entries({jobStatus:state.jobStatus,educationChoice:state.educationChoice,...state.notes}).map(([key,value])=>({key,value}))
 };
}
const datasets=[['goals','Goals'],['daily','Daily entries'],['diary','Diary entries'],['tasks','Daily tasks'],['checks','Daily checkboxes'],['weekly','Weekly progress'],['targets','Weekly targets'],['monthly','Monthly reviews'],['yearly','Yearly reviews'],['savings','Savings'],['notes','Preferences & notes']];
function datasetRows(){const rows=collectData()[dataDataset]||[];const query=dataFilter.toLowerCase().trim();return query?rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(query))):rows}
function tableMarkup(){
 const rows=datasetRows();const columns=Object.keys(collectData()[dataDataset]?.[0]||{});
 if(!rows.length)return '<p class="tiny" style="padding:18px">No matching records yet. As you use the planner, they will appear here.</p>';
 return `<table class="data-table"><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td title="${esc(r[c])}">${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
}
function renderDataTable(){const target=document.getElementById('dataTableWrap');if(target)target.innerHTML=tableMarkup();const n=document.getElementById('dataResultCount');if(n)n.textContent=datasetRows().length+' rows'}
function renderData(){
 const sets=collectData();const total=Object.values(sets).reduce((sum,rows)=>sum+rows.length,0);
 const status=dbMode?`<div class="storage-status"><b>SQLite connected ✓</b> — All edits are also written to <code>data/planner.sqlite3</code> on this computer. ${dbUpdated?'Last database save: '+esc(dbUpdated):''}</div>`:
 '<div class="storage-status warning"><b>Browser-only mode.</b> Entries are currently in localStorage, not a database file. Export JSON now or start the included <code>server.py</code> to create a real SQLite database.</div>';
 document.getElementById('page-data').innerHTML=heading('SEE WHERE YOUR INFORMATION GOES','Data explorer','View every stored record, search tables and download a portable copy.')+
 `<div class="grid"><div class="panel span12">${status}<div class="row between wrap" style="margin:19px 0"><div><h2>Saved records</h2><div class="tiny">${total} records across ${datasets.length} logical tables · read-only viewer</div></div><div class="row wrap"><button class="action secondary" data-export="1">Download JSON backup</button><button class="action secondary" data-csv="1">Export shown CSV</button>${dbMode?'<button class="action" data-dbdownload="1">Download SQLite database</button>':''}</div></div><div class="data-toolbar"><div class="field"><label for="dataDataset">Choose table</label><select id="dataDataset">${datasets.map(([key,label])=>`<option value="${key}" ${dataDataset===key?'selected':''}>${label} (${sets[key].length})</option>`).join('')}</select></div><div class="field"><label for="dataFilter">Search records</label><input id="dataFilter" placeholder="Search dates, notes, goals…" value="${esc(dataFilter)}"></div><span class="tiny" id="dataResultCount">${datasetRows().length} rows</span></div><div id="dataTableWrap" class="data-table-wrap">${tableMarkup()}</div><details style="margin-top:22px"><summary style="cursor:pointer;font-weight:750">Inspect complete raw JSON</summary><pre class="data-mono">${esc(JSON.stringify(state,null,2))}</pre></details></div><div class="panel span12"><h2>Where your data lives</h2><p class="muted">When opened directly as a file, this app uses your browser's <code>localStorage</code> under the exact key <code>${STORE}</code>. When opened through the local Python server, it also saves to a real SQLite file in the <code>data</code> folder. The original app and this version may have separate browser storage even on the same computer — use JSON export/import to transfer your existing progress.</p><div class="callout teal"><b>Recommended:</b> Run the Python server, then use “Download SQLite database” to make a standalone database backup. You can open the database with DB Browser for SQLite or the SQLite extension in VS Code.</div></div></div>`;
}
function exportCsv(){
 const records=datasetRows();if(!records.length){alert('No matching records to export.');return}
 const fields=Object.keys(records[0]);
 const csv=[fields,...records.map(r=>fields.map(f=>r[f]??''))].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');
 const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);
 const link=document.createElement('a');link.href=url;link.download='planner_'+dataDataset+'_'+iso(new Date())+'.csv';link.click();URL.revokeObjectURL(url);
}
function renderSettings(){document.getElementById('page-settings').innerHTML=heading('MAKE IT YOUR OWN','Settings & backup','Adjust targets and download a copy of your data.')+`<div class="grid"><div class="panel span7"><h2>Weekly targets</h2><p class="tiny">Set goals that feel achievable in your current situation.</p><div class="two-cols">${weeklyItems().map(([k,title])=>`<div class="field"><label for="set_${k}">${title}</label><input id="set_${k}" type="number" data-weekgoal="${k}" min="1" max="99" value="${target(k)}"></div>`).join('')}</div><div class="callout teal" style="margin-top:20px">A sustainable weekly plan matters more than perfect completion. You can lower targets whenever life changes.</div></div><div class="panel span5"><h2>Privacy & data</h2><p><button class="action secondary" data-page="data">Explore my saved records →</button></p><p class="tiny">Your entries stay in this browser’s local storage when permitted. They are not uploaded to an account or synchronised across devices. Private browsing, storage restrictions or clearing browser data may remove them.</p><div class="list"><button class="action" data-export="1">↓ Export my data (.json)</button><label class="action secondary" style="text-align:center;cursor:pointer">↑ Import saved data (.json)<input id="importJson" accept="application/json,.json" type="file" style="display:none"></label><button class="action danger" data-reset="1">Reset planner to starter data</button></div><div class="rule"></div><button class="action outline" data-page="reviews">Open progress & reviews →</button><div class="note" style="margin-top:15px">Tip: export a backup regularly and keep it in your own Drive or files.</div></div></div>`}
function render(){const savedScroll=window.scrollY;const scheduleExpanded=document.querySelector('.calendar-manage')?.open;const calendarScroll=document.querySelector('.calendar-scroll')?.scrollTop;ensureDiaryEntries();applyProfile();renderNav();renderOverview();renderDaily();renderDayTodos();renderWeekly();renderGoals();renderReviews();renderFinance();renderData();renderSettings();renderPersonalisation();renderProgress();renderHomeDayPanels();renderSchedule();renderScheduledDaily();document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+page));let saveEl=document.querySelector('#page-'+page+' #saveState');if(saveEl)saveEl.textContent='Changes save automatically';showSetup();if(scheduleExpanded){const manager=document.querySelector('.calendar-manage');if(manager)manager.open=true}if(calendarScroll!=null){const calendar=document.querySelector('.calendar-scroll');if(calendar)calendar.scrollTop=calendarScroll}window.scrollTo({top:savedScroll,behavior:'instant'})}
function go(id){if(!nav.some(x=>x[0]===id))return;page=id;history.replaceState(null,'',location.pathname+'#'+id);document.getElementById('mobileDropdown').classList.add('hidden');render();window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.menu){document.getElementById('mobileDropdown').classList.toggle('hidden');return}if(btn.dataset.page){go(btn.dataset.page);return}if(btn.dataset.counter){let s=statsFor(thisWeek());let k=btn.dataset.counter;s[k]=Math.max(0,Math.min(999,Number(s[k]||0)+Number(btn.dataset.n)));save();render();return}if(btn.dataset.daymove){let d=parseDate(day);d.setDate(d.getDate()+Number(btn.dataset.daymove));day=iso(d);render();return}if(btn.dataset.choice){state.educationChoice=btn.dataset.choice;save();render();return}if(btn.dataset.goaldelete){if(confirm('Remove this goal?')){state.goals=state.goals.filter(x=>x.id!==btn.dataset.goaldelete);save();render()}return}if(btn.dataset.clearweek){if(confirm('Clear counts for this week?')){state.weeklyStats[thisWeek()]={};save();render()}return}if(btn.dataset.csv){exportCsv();return}if(btn.dataset.dbdownload){if(dbMode)location.href='/api/download-db';return}if(btn.dataset.export){const data=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const href=URL.createObjectURL(data);const a=document.createElement('a');a.href=href;a.download='Planner_Backup_'+iso(new Date())+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1500);return}if(btn.dataset.reset){if(confirm('Reset all planner data? Export a backup first if you want to keep it.')){state=clone(DEFAULT);save();render()}return}});
document.addEventListener('change',async e=>{let t=e.target;if(t.dataset.daily){dstate().checks[t.dataset.daily]=t.checked;save();render();return}if(t.dataset.goalcheck){const g=state.goals.find(x=>x.id===t.dataset.goalcheck);if(g)g.done=t.checked;save();render();return}if(t.id==='dayPicker'){if(t.value){day=t.value;render()}return}if(t.id==='dataDataset'){dataDataset=t.value;dataFilter='';renderData();return}if(t.id==='reviewMonth'){if(t.value){reviewMonth=t.value;reviewNotice='';render()}return}if(t.id==='reviewYear'){reviewYear=Number(t.value);reviewNotice='';render();return}if(t.id==='jobStatus'){state.jobStatus=t.value;save();return}if(t.dataset.money){updateSavingsInput(t);return}if(t.dataset.weekgoal){state.weeklyGoals[t.dataset.weekgoal]=Math.min(99,Math.max(1,Number(t.value)||1));save();render();return}if(t.id==='importJson'){const f=t.files?.[0];if(!f)return;try{const json=JSON.parse(await f.text());if(!json||json.version!==1||!Array.isArray(json.goals)||!json.weeklyGoals||!json.daily||!json.weeklyStats||!json.finance)throw Error('Invalid or unsupported backup');if(confirm('Replace current data with this backup?')){state={...clone(DEFAULT),...json};save();render();alert('Backup imported successfully.')}}catch(err){alert('Could not import this backup: '+err.message)}return}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='dataFilter'){dataFilter=t.value;renderDataTable();return}if(t.dataset.monthfield){(state.monthReviews[reviewMonth]||(state.monthReviews[reviewMonth]={}))[t.dataset.monthfield]=t.value;save()}else if(t.dataset.yearfield){(state.yearReviews[reviewYear]||(state.yearReviews[reviewYear]={}))[t.dataset.yearfield]=t.value;save()}else if(t.id==='dailyNote'){dstate().note=t.value;save()}else if(t.id==='careerNote'){state.notes.career=t.value;save()}else if(t.id==='educationNote'){state.notes.education=t.value;save()}else if(t.id==='monthlyNote'){state.notes.monthly=t.value;save()}});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='newGoalForm'){e.preventDefault();const name=document.getElementById('newGoalTitle').value.trim();if(!name)return;state.goals.push({id:'g'+Date.now()+'_'+Math.floor(Math.random()*1000),title:name,area:document.getElementById('newGoalArea').value,due:document.getElementById('newGoalDue').value,done:false});save();render()}});

function profile(){return {name:'My',theme:'sage',intention:'Build a life that feels like mine.',...(state.profile||{})}}
function habits(){return Array.isArray(state.habits)?state.habits:[]}
function applyProfile(){const p=profile();document.documentElement.dataset.theme=['sage','rose','blue'].includes(p.theme)?p.theme:'sage';document.querySelector('.brand-name').textContent='Planner';document.querySelector('.brand p').textContent=p.intention;document.title='Planner'}
function renderPersonalisation(){
const p=profile();document.getElementById('page-settings').insertAdjacentHTML('afterbegin',`<div class="panel personal-panel"><div class="eyebrow">A LITTLE MORE YOU</div><h2>Your space, your rhythm</h2><form id="profileForm" class="two-cols"><div class="field"><label for="profileName">Your name</label><input id="profileName" maxlength="40" required value="${esc(p.name)}"></div><div class="field"><label for="profileTheme">Colour palette</label><select id="profileTheme">${[['sage','Sage & cream'],['rose','Rose & linen'],['blue','Blue & mist']].map(([v,l])=>`<option value="${v}" ${p.theme===v?'selected':''}>${l}</option>`).join('')}</select><small id="profileThemeStatus" role="status" aria-live="polite">Changes apply immediately.</small></div><div class="field"><label for="profileIntention">A personal intention</label><input id="profileIntention" maxlength="120" value="${esc(p.intention)}"></div><div><button class="action" type="submit">Save my style</button></div></form><div class="rule"></div><button class="action outline" data-setup="1">Edit my goals & routine</button><h3>Daily habits</h3><p class="tiny">Add habits that matter to you. Removing a habit keeps its past check-ins in your backup and progress totals.</p><div class="list">${habits().map(([id,title])=>`<div class="row between"><span>${esc(title)}</span><button class="smallbtn" type="button" data-removehabit="${esc(id)}" aria-label="Remove ${esc(title)}">×</button></div>`).join('')}</div><form id="habitForm" class="row wrap" style="margin-top:18px"><label for="habitName">New habit</label><input id="habitName" maxlength="80" required placeholder="e.g. Read for 15 minutes"><button class="action" type="submit">Add habit</button></form></div>`);
}
function periodStats(prefix){const entries=Object.entries(state.daily).filter(([date])=>date.startsWith(prefix)&&date<=iso(new Date()));return {days:entries.filter(([,v])=>Object.values(v.checks||{}).some(Boolean)).length,checks:entries.reduce((n,[,v])=>n+Object.values(v.checks||{}).filter(Boolean).length,0),goals:state.goals.filter(g=>g.due?.startsWith(prefix)),done:state.goals.filter(g=>g.due?.startsWith(prefix)&&g.done).length}}
function progressCard(prefix,title){const s=periodStats(prefix);return `<div class="panel span6"><div class="eyebrow">${title}</div><h2>${s.days} days of showing up</h2><p>${s.checks} habit & schedule check-ins · ${s.done} / ${s.goals.length} goals due in this period completed</p>${meter(s.goals.length?s.done/s.goals.length*100:0,'green')}<p class="tiny">Goal progress is based on target dates. Future daily check-ins are excluded.</p></div>`}
function renderProgress(){document.getElementById('page-overview').insertAdjacentHTML('afterbegin',`<div class="personal-banner"><span>YOUR SPACE TO GROW</span><p>${esc(profile().intention)}</p><button class="action outline" data-page="settings">Personalise my planner ↗</button></div>`)}
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='profileForm'){e.preventDefault();state.profile={name:document.getElementById('profileName').value.trim()||'My',theme:document.getElementById('profileTheme').value,intention:document.getElementById('profileIntention').value.trim()};save();render()}if(e.target.getAttribute('id')==='habitForm'){e.preventDefault();const title=document.getElementById('habitName').value.trim();if(!title)return;state.habits=[...habits(),['habit_'+crypto.randomUUID(),title,'A small step for yourself']];save();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-removehabit]');if(!b)return;if(confirm('Remove this habit from your daily list? Past check-ins will be kept.')){state.habits=habits().filter(h=>h[0]!==b.dataset.removehabit);save();render()}});


function setupLines(value){return value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20)}
function completeSetup(values){
 const old=habits();const chosen=setupLines(values.daily);const next=chosen.map(title=>old.find(h=>h[1]===title)||['habit_'+crypto.randomUUID(),title,'Your chosen daily action']);
 state.profile={...profile(),name:values.name.trim()};state.plan={main:values.main.trim(),monthly:values.monthly.trim(),yearly:values.yearly.trim(),rhythm:values.rhythm};state.habits=next;
 state.weeklyItems=next.map(([id,title])=>[id,title,'Sessions this week']);next.forEach(([id])=>{if(!state.weeklyGoals[id])state.weeklyGoals[id]=Number(values.frequency)});
 // Remove only untouched template goals, preserving completed or edited entries.
 state.goals=state.goals.filter(g=>!DEFAULT.goals.some(d=>d.id===g.id&&d.title===g.title&&!g.done));
 const now=new Date(),monthEnd=iso(new Date(now.getFullYear(),now.getMonth()+1,0)),yearEnd=now.getFullYear()+'-12-31';
 for(const [period,title,due] of [['monthly',values.monthly,monthEnd],['yearly',values.yearly,yearEnd]]){const id='setup_'+period;const existing=state.goals.find(g=>g.id===id);if(existing){if(existing.title!==title.trim())existing.done=false;existing.title=title.trim();existing.due=due}else state.goals.push({id,title:title.trim(),due,area:'Personal',done:false})}
 (state.monthReviews[iso(now).slice(0,7)]||={}).focus=values.monthly.trim();(state.yearReviews[now.getFullYear()]||={}).focus=values.yearly.trim();state.onboardingComplete=true;
}
function showSetup(force=false){if(state.onboardingComplete&&!force)return;if(document.getElementById('welcomeDialog'))return;
 const p=state.plan||{},dialog=document.createElement('dialog');dialog.id='welcomeDialog';dialog.setAttribute('aria-labelledby','welcomeTitle');dialog.innerHTML=`<form id="welcomeForm"><div class="eyebrow">🎯 A PLANNER THAT STARTS WITH YOU</div><h1 id="welcomeTitle">Let’s make it yours.</h1><p class="muted">Tell us what matters to you. You can change everything later in Settings.</p><div class="field"><label for="welcomeName">What should we call you?</label><input id="welcomeName" name="name" required maxlength="40" autocomplete="given-name" value="${esc(state.profile?.name||'')}"></div><div class="field"><label for="welcomeMain">What are your main goals right now?</label><textarea id="welcomeMain" name="main" required maxlength="500" placeholder="Health, creativity, family, studies—anything that matters to you.">${esc(p.main||'')}</textarea></div><div class="field"><label for="welcomeDaily">What would you like your daily goals to look like?</label><textarea id="welcomeDaily" name="daily" required maxlength="1600" placeholder="One habit per line, for example:&#10;Walk for 20 minutes&#10;Read 10 pages">${esc(habits().map(h=>h[1]).join('\n'))}</textarea><small>One habit per line, up to 20. These also become your weekly targets.</small></div><div class="two-cols"><div class="field"><label for="welcomeFrequency">How many times a week feels realistic?</label><select id="welcomeFrequency" name="frequency"><option value="3">3 times a week</option><option value="5">5 times a week</option><option value="7">Every day</option><option value="1">Once a week</option></select><small>You can adjust each target separately later.</small></div><div class="field"><label for="welcomeRhythm">What kind of routine suits you?</label><select id="welcomeRhythm" name="rhythm">${['Gentle and flexible','A balanced routine','Structured and focused'].map(v=>`<option ${p.rhythm===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="welcomeMonthly">What would you like to achieve this month?</label><textarea id="welcomeMonthly" name="monthly" required maxlength="500" placeholder="One outcome you would feel proud of">${esc(p.monthly||'')}</textarea></div><div class="field"><label for="welcomeYearly">What would a meaningful year look like?</label><textarea id="welcomeYearly" name="yearly" required maxlength="500" placeholder="Your bigger goal for this year">${esc(p.yearly||'')}</textarea></div><p class="tiny">Your answers are saved on this device. Monthly and yearly answers become goals with end-of-period target dates.</p><div class="row wrap"><button class="action" type="submit">${state.onboardingComplete?'Save my plan':'Create my planner'} →</button>${state.onboardingComplete?'<button class="action outline" type="button" data-close-setup="1">Cancel</button>':''}</div></form>`;
 if(!state.onboardingComplete)dialog.insertAdjacentHTML('beforeend',`<div class="rule"></div><label class="action outline" style="display:inline-block;cursor:pointer">Already have a planner? Import JSON backup<input id="welcomeBackup" type="file" accept=".json,application/json" hidden></label><p class="tiny">Bring your existing goals, timetable and progress into this browser.</p>`);if(window.PLANNER_PUBLIC_DEMO&&!state.onboardingComplete)dialog.insertAdjacentHTML('afterbegin',`<div class="public-sample-start"><button type="button" class="action" data-public-sample="1">Explore sample planner →</button><p class="tiny">Try the features with fictional sample data, or complete your own setup below.</p></div>`);document.body.appendChild(dialog);dialog.addEventListener('cancel',e=>{if(!state.onboardingComplete)e.preventDefault();else dialog.remove()});dialog.showModal();
}
document.addEventListener('click',e=>{if(e.target.closest('[data-setup]'))showSetup(true);if(e.target.closest('[data-close-setup]'))document.getElementById('welcomeDialog')?.remove()});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='welcomeForm')return;e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!values.name.trim()||!values.main.trim()||!setupLines(values.daily).length||!values.monthly.trim()||!values.yearly.trim()){alert('Please fill in each answer, including at least one daily habit.');return}completeSetup(values);save();document.getElementById('welcomeDialog').remove();render()});


function updateGoal(id,title,area,due){const goal=state.goals.find(g=>g.id===id);if(!goal||!title.trim())return false;goal.title=title.trim();goal.area=area.trim()||'Personal';goal.due=due;
 if(state.plan&&id==='setup_monthly')state.plan.monthly=goal.title;
 if(state.plan&&id==='setup_yearly')state.plan.yearly=goal.title;
 return true;
}
function editGoal(id){const g=state.goals.find(x=>x.id===id);if(!g)return;document.getElementById('editGoalDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='editGoalDialog';dialog.setAttribute('aria-labelledby','editGoalHeading');dialog.innerHTML=`<form id="editGoalForm"><h2 id="editGoalHeading">Edit goal</h2><input type="hidden" name="goalId" value="${esc(g.id)}"><div class="field"><label for="editGoalTitle">What do you want to do?</label><input id="editGoalTitle" name="title" required maxlength="500" value="${esc(g.title)}"></div><div class="field"><label for="editGoalArea">Area</label><input id="editGoalArea" name="area" required maxlength="80" list="goalAreaOptions" value="${esc(g.area)}"><datalist id="goalAreaOptions"><option>Career</option><option>Skills</option><option>Education</option><option>Finance</option><option>Personal</option><option>Health</option></datalist></div><div class="field"><label for="editGoalDue">Target date (optional)</label><input id="editGoalDue" name="due" type="date" value="${esc(g.due||'')}"></div><div class="row wrap"><button class="action" type="submit">Save changes</button><button class="action outline" type="button" data-cancel-goal="1">Cancel</button></div></form>`;document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal()}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(button?.dataset.goaledit){e.preventDefault();editGoal(button.dataset.goaledit)}if(button?.dataset.cancelGoal)document.getElementById('editGoalDialog')?.remove()});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='editGoalForm')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!updateGoal(v.goalId,v.title,v.area,v.due)){document.getElementById('editGoalTitle').setCustomValidity('Please enter a goal.');document.getElementById('editGoalTitle').reportValidity();return}save();document.getElementById('editGoalDialog').remove();render()});
document.addEventListener('input',e=>{if(e.target.getAttribute('id')==='editGoalTitle')e.target.setCustomValidity('')});

const weekNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function scheduleEntries(date){return [...(state.schedule||[]).filter(s=>date>=s.from&&(!s.until||date<=s.until)&&s.days.includes(parseDate(date).getDay())).map(s=>({...s,...(state.scheduleExceptions?.[date]?.[s.id]||{})})),...importedEntries(date)].sort((a,b)=>a.time.localeCompare(b.time))}
function scheduleSummary(prefix){let done=0;for(const [date,v] of Object.entries(state.daily)){if(date.startsWith(prefix)&&date<=iso(new Date()))done+=Object.entries(v.checks||{}).filter(([id,value])=>id.startsWith('schedule_')&&value).length}return done}
function scheduleWeek(){let total=0,done=0;for(let n=0;n<7;n++){let d=parseDate(thisWeek());d.setDate(d.getDate()+n);const date=iso(d);for(const s of scheduleEntries(date)){if(s.skip)continue;total++;if(state.daily[date]?.checks?.['schedule_'+s.id])done++}}return {total,done}}
function applyScheduleEdit(id,entry,effective){state.schedule||=[];const old=state.schedule.find(s=>s.id===id);if(old){if(effective<old.from)throw Error('The change cannot start before this activity begins.');if(old.until&&effective>old.until)throw Error('The change must start within this activity’s date range.');const previous=parseDate(effective);previous.setDate(previous.getDate()-1);old.until=iso(previous)}state.schedule.push({...entry,id:crypto.randomUUID(),from:effective})}
function scheduleDialog(id='',date=''){if(date&&importedEntries(date).some(e=>e.id===id)){const imported=importedEntries(date).find(e=>e.id===id);const dialog=document.createElement('dialog');dialog.id='scheduleDialog';dialog.innerHTML=`<h2>${esc(imported.title)}</h2><p>${esc(imported.calendarName)} · ${date} · ${esc(imported.time)}${imported.end?' – '+esc(imported.end):''}</p><p>${esc(imported.location||'')}</p><p>Imported events are managed by the original calendar. You can complete or skip this occurrence in Daily routine.</p><button class="action" data-page="daily" data-schedule-close="1">Open daily routine</button><button class="action outline" data-schedule-close="1">Close</button>`;document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal();return;}const source=id?(state.schedule||[]).find(s=>s.id===id):null;const s=date?scheduleEntries(date).find(s=>s.id===id):source;const today=iso(new Date());const dialog=document.createElement('dialog');dialog.id='scheduleDialog';dialog.setAttribute('aria-labelledby','scheduleHeading');dialog.innerHTML=`<form id="scheduleForm"><h2 id="scheduleHeading">${date?'Change this day':id?'Edit schedule':'Add an activity'}</h2><input type="hidden" name="scheduleId" value="${esc(id)}"><input type="hidden" name="date" value="${date}"><div class="field"><label for="scheduleTitle">Activity or class</label><input id="scheduleTitle" name="title" maxlength="120" required value="${esc(s?.title||'')}" placeholder="e.g. Biology lecture"></div><div class="two-cols"><div class="field"><label for="scheduleTime">Start time</label><input id="scheduleTime" name="time" type="time" required value="${s?.time||'09:00'}"></div><div class="field"><label for="scheduleEnd">End time (optional)</label><input id="scheduleEnd" name="end" type="time" value="${s?.end||''}"><small>For overnight sessions, use two activities.</small></div></div>${date?'':`<fieldset><legend>Repeats on</legend><div class="row wrap">${[1,2,3,4,5,6,0].map(n=>`<label><input type="checkbox" name="days" value="${n}" ${s?.days.includes(n)?'checked':''}> ${weekNames[n].slice(0,3)}</label>`).join('')}</div></fieldset><div class="two-cols"><div class="field"><label for="scheduleFrom">${id?'Change from':'Start date'}</label><input id="scheduleFrom" name="from" type="date" required min="${today}" value="${source&&source.from>today?source.from:today}"></div><div class="field"><label for="scheduleUntil">Semester / schedule end (optional)</label><input id="scheduleUntil" name="until" type="date" value="${s?.until||''}"></div></div><p class="tiny">Past dates and completed sessions stay unchanged. Set an end date for semester classes; add the next semester as new activities.</p>`}<p id="scheduleError" role="alert"></p><div class="row wrap"><button class="action" type="submit">Save activity</button><button class="action outline" type="button" data-schedule-close="1">Cancel</button></div></form>`;document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal()}

function renderScheduledDaily(){const entries=scheduleEntries(day),checks=state.daily[day]?.checks||{};document.getElementById('page-daily').insertAdjacentHTML('beforeend',`<div class="panel" style="margin-top:24px"><div class="row between wrap"><div><h2>Today’s scheduled goals</h2><p class="tiny">${day} · ${entries.filter(s=>!s.skip&&checks['schedule_'+s.id]).length}/${entries.filter(s=>!s.skip).length} completed</p></div><button class="action outline" data-page="schedule">Manage schedule</button></div>${entries.map(s=>`<div class="schedule-item row between wrap"><label class="row"><input type="checkbox" data-schedule-check="${esc(s.id)}" ${checks['schedule_'+s.id]?'checked':''} ${s.skip?'disabled':''}><span><strong>${esc(s.title)}</strong><br><small>${esc(s.time)}${s.end?' – '+esc(s.end):' onward'}${s.skip?' · Skipped':''}</small></span></label><div class="row"><button class="action outline" data-schedule-day="${esc(s.id)}">Edit this day</button><button class="action outline" data-schedule-skip="${esc(s.id)}">${s.skip?'Restore':'Skip'}</button></div></div>`).join('')||'<p>No scheduled activities for this date. Add a recurring activity in My schedule.</p>'}<p class="tiny">Flexible daily habits and timed sessions are tracked separately.</p></div>`);const w=scheduleWeek();document.getElementById('page-weekly').insertAdjacentHTML('afterbegin',`<div class="panel" style="margin-bottom:24px"><h2>Scheduled sessions this week</h2><p>${w.done} of ${w.total} completed · automatically counted from Daily routine</p>${meter(w.total?100*w.done/w.total:0)}<button class="action outline" data-page="schedule">View timetable</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.scheduleEdit||b.dataset.scheduleDay||b.dataset.scheduleStop||b.dataset.scheduleSkip;if(b.dataset.scheduleAdd)scheduleDialog();if(b.dataset.scheduleEdit)scheduleDialog(id);if(b.dataset.scheduleDay)scheduleDialog(id,day);if(b.dataset.scheduleClose)document.getElementById('scheduleDialog')?.remove();if(b.dataset.scheduleStop&&confirm('End this activity from today? Past sessions and progress will stay saved.')){const s=state.schedule.find(s=>s.id===id),d=parseDate(iso(new Date()));d.setDate(d.getDate()-1);s.until=iso(d);save();render()}if(b.dataset.scheduleSkip){state.scheduleExceptions||={};state.scheduleExceptions[day]||={};const item=state.scheduleExceptions[day][id]||{};item.skip=!item.skip;state.scheduleExceptions[day][id]=item;if(item.skip&&state.daily[day]?.checks)state.daily[day].checks['schedule_'+id]=false;save();render()}});
document.addEventListener('change',e=>{if(!e.target.dataset.scheduleCheck)return;dstate().checks||={};dstate().checks['schedule_'+e.target.dataset.scheduleCheck]=e.target.checked;save();render()});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='scheduleForm')return;e.preventDefault();const form=new FormData(e.target),v=Object.fromEntries(form),days=form.getAll('days').map(Number);try{if(!v.title.trim())throw Error('Enter an activity name.');if(v.end&&v.end<=v.time)throw Error('End time must be after the start time.');if(!v.date){if(!days.length)throw Error('Choose at least one day.');if(v.from<iso(new Date()))throw Error('Choose today or a future start date.');if(v.until&&v.until<v.from)throw Error('The end date must be on or after the start date.');applyScheduleEdit(v.scheduleId,{title:v.title.trim(),time:v.time,end:v.end,days,until:v.until},v.from)}else{state.scheduleExceptions||={};state.scheduleExceptions[v.date]||={};state.scheduleExceptions[v.date][v.scheduleId]={...(state.scheduleExceptions[v.date][v.scheduleId]||{}),title:v.title.trim(),time:v.time,end:v.end}}save();document.getElementById('scheduleDialog').remove();render()}catch(error){document.getElementById('scheduleError').textContent=error.message}});

let calendarWeek=thisWeek();
function calendarDays(start){return Array.from({length:7},(_,i)=>{const d=parseDate(start);d.setDate(d.getDate()+i);return iso(d)})}
function calendarEvents(date){const laneEnds=[];const events=scheduleEntries(date).filter(s=>!s.skip).map(s=>{const [h,m]=s.time.split(':').map(Number);const start=h*60+m;const [eh,em]=(s.end||'').split(':').map(Number);const end=s.end?eh*60+em:Math.min(1440,start+60);return {...s,start,endMinute:Math.max(start+15,end)}});for(const e of events){let lane=laneEnds.findIndex(end=>end<=e.start);if(lane<0)lane=laneEnds.length;e.lane=lane;laneEnds[lane]=e.endMinute}return events.map(e=>({...e,lanes:Math.max(1,laneEnds.length)}))}
function renderSchedule(){const dates=calendarDays(calendarWeek),today=iso(new Date()),first=parseDate(dates[0]),last=parseDate(dates[6]);const range=first.toLocaleDateString('en-MY',{day:'numeric',month:'short'})+' – '+last.toLocaleDateString('en-MY',{day:'numeric',month:'short',year:'numeric'});document.getElementById('page-schedule').innerHTML=heading('YOUR WEEK AT A GLANCE','My schedule','Classes, routines and time for yourself.')+calendarPanel()+`<div class="panel calendar-panel"><div class="row between wrap calendar-toolbar"><div class="row wrap"><button class="action outline" data-calendar-today="1">Today</button><button class="smallbtn" data-calendar-move="-1" aria-label="Previous week">‹</button><button class="smallbtn" data-calendar-move="1" aria-label="Next week">›</button><h2>${esc(range)}</h2></div><button class="action" data-schedule-add="1">+ Add activity</button></div><p class="tiny">Week view · Click an activity to edit that day. Use Manage recurring activities below to edit a repeating activity or semester dates.</p><div class="calendar-scroll"><div class="calendar-grid"><div class="calendar-corner">TIME</div>${dates.map(date=>`<div class="calendar-date ${date===today?'is-today':''}"><span>${parseDate(date).toLocaleDateString('en-MY',{weekday:'short'})}</span><b>${parseDate(date).getDate()}</b></div>`).join('')}<div class="calendar-hours">${Array.from({length:24},(_,h)=>`<span style="top:${h*60}px">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${dates.map(date=>`<div class="calendar-day ${date===today?'is-today':''}">${calendarEvents(date).map(e=>`<button type="button" class="calendar-event tone-${e.title.length%4} ${state.daily[date]?.checks?.['schedule_'+e.id]?'event-done':''}" style="top:${e.start}px;height:${Math.max(24,e.endMinute-e.start)}px;left:calc(${100*e.lane/e.lanes}% + 3px);width:calc(${100/e.lanes}% - 6px)" data-calendar-event="${esc(e.id)}" data-calendar-date="${date}" aria-label="${esc(e.title)}, ${date}, ${e.time}${e.end?' to '+e.end:''}"><strong>${esc(e.title)}</strong><span>${esc(e.time)}${e.end?' – '+esc(e.end):' onward'}</span>${state.daily[date]?.checks?.['schedule_'+e.id]?'<span>✓ Completed</span>':''}</button>`).join('')}${date===today?`<div class="calendar-now" style="top:${new Date().getHours()*60+new Date().getMinutes()}px" aria-label="Current time"></div>`:''}</div>`).join('')}</div></div><p class="tiny">Activities appear automatically in Daily routine during their date range. Times use your device’s local timezone. An activity without an end time is displayed as a one-hour block.</p></div><details class="panel calendar-manage"><summary>Manage recurring activities & semesters</summary><div class="schedule-days">${(state.schedule||[]).filter(s=>(!s.until||s.until>=today)&&(!s.until||s.until>=s.from)).map(s=>`<div class="schedule-item"><strong>${esc(s.title)}</strong><p class="tiny">${s.days.map(n=>weekNames[n].slice(0,3)).join(', ')} · ${esc(s.time)}${s.end?' – '+esc(s.end):''}<br>${s.from} → ${s.until||'No end date'}</p><div class="row wrap"><button class="action outline" data-schedule-edit="${esc(s.id)}">Edit</button><button class="action outline" data-schedule-stop="${esc(s.id)}">End from today</button></div></div>`).join('')||'<p>No recurring activities yet. Add an activity to build your calendar.</p>'}</div></details>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.calendarMove){const d=parseDate(calendarWeek);d.setDate(d.getDate()+7*Number(b.dataset.calendarMove));calendarWeek=iso(d);renderSchedule()}if(b.dataset.calendarToday){calendarWeek=thisWeek();renderSchedule()}if(b.dataset.calendarEvent){day=b.dataset.calendarDate;scheduleDialog(b.dataset.calendarEvent,day)}});

let calendarPreview=null,calendarBusy=false;
function calendarSources(){return state.calendarSources||[]}
function importedEntries(date){return calendarSources().flatMap(source=>(source.occurrences||[]).filter(e=>e.date===date).map(e=>({...e,calendarName:source.name,imported:true,...(state.scheduleExceptions?.[date]?.[e.id]||{})})))}
function calendarPanel(){return `<div class="panel calendar-connections"><div class="row between wrap"><div><h2>Connected calendars</h2><p class="tiny">${window.PLANNER_PUBLIC_DEMO?'Import an .ics file to try calendar events. Live subscriptions need a backend.':'Subscribe to an HTTPS / webcal feed, or upload an .ics snapshot.'}</p></div><button class="action outline" data-calendar-connect="1">${window.PLANNER_PUBLIC_DEMO?'Import calendar file':'Connect calendar'}</button></div>${calendarSources().map(source=>`<div class="schedule-item row between wrap"><div><strong>${esc(source.name)}</strong><p class="tiny">${source.type==='link'?(window.PLANNER_PUBLIC_DEMO?'Imported calendar snapshot · live refresh unavailable in this demo':'Subscription · refreshes every 30 minutes while open'):'File import · one-time snapshot'}<br>Last updated: ${source.lastSync?esc(new Date(source.lastSync).toLocaleString()):'Never'}<br>Loaded ${source.from||''} through ${source.until||''}${source.error?'<br><span role="status">'+esc(source.error)+'</span>':''}</p></div><div class="row wrap">${source.type==='link'&&!window.PLANNER_PUBLIC_DEMO?`<button class="action outline" data-calendar-refresh="${source.id}" ${calendarBusy?'disabled':''}>Refresh now</button>`:''}<button class="action outline" data-calendar-disconnect="${source.id}">Disconnect</button></div></div>`).join('')||'<p class="tiny">No calendar connected yet.</p>'}<p class="tiny">Imports cover the past 90 days and next 12 months. Provider changes replace imported events; your completion history is kept. Subscription links are stored on this device and included in JSON backups—keep backups private.</p><p id="calendarRefreshStatus" class="tiny" role="status">${calendarBusy?'Refreshing calendars…':''}</p></div>`}
function connectCalendar(){calendarPreview=null;const dialog=document.createElement('dialog');dialog.id='calendarConnectDialog';dialog.setAttribute('aria-labelledby','connectCalendarHeading');dialog.innerHTML=`<form id="calendarConnectForm"><h2 id="connectCalendarHeading">Connect a calendar</h2><p class="muted">Preview events before adding them to your daily routine.</p><div class="field"><label for="calendarSourceName">Calendar name (optional)</label><input id="calendarSourceName" name="name" maxlength="100" placeholder="University timetable"></div><div class="field ${window.PLANNER_PUBLIC_DEMO?'hidden':''}"><label for="calendarSourceUrl">Subscription link</label><input id="calendarSourceUrl" name="url" type="text" maxlength="4096" autocomplete="off" spellcheck="false" placeholder="https://…/calendar.ics or webcal://…"><small>Use an .ics subscription URL, not a calendar sharing page. The link is sent to this planner’s server to retrieve events.</small></div><div class="field"><label for="calendarSourceFile">Or upload an .ics file</label><input id="calendarSourceFile" name="file" type="file" accept=".ics,text/calendar"><small>${window.PLANNER_PUBLIC_DEMO?'This demo supports file imports. Your file is processed in this browser.':'Choose either a link or a file. Files do not automatically refresh.'}</small></div><p id="calendarConnectError" role="alert"></p><div id="calendarPreview"></div><div class="row wrap"><button class="action" id="calendarPreviewButton" type="submit">Preview calendar</button><button class="action" type="button" id="calendarConfirmButton" data-calendar-confirm="1" hidden>Add to my planner</button><button class="action outline" type="button" data-calendar-connect-close="1">Cancel</button></div></form>`;document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>{calendarPreview=null;dialog.remove()});dialog.showModal()}
async function fetchCalendarText(url){if(window.PLANNER_PUBLIC_DEMO)throw Error('Live calendar subscriptions need a backend. Upload an .ics file in this public demo.');const response=await fetch('/api/calendar-fetch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url}),signal:AbortSignal.timeout(25000)});let result;try{result=await response.json()}catch{throw Error('Calendar links need the updated planner server. Restart the local server or use the hosted planner. You can also upload an .ics file.')}if(!response.ok)throw Error(result.error||'Unable to retrieve the calendar.');return result.calendar}
async function parseSource(text,id){if(!window.PlannerCalendar)throw Error('Calendar parser is still loading. Try again in a moment.');return window.PlannerCalendar.parseCalendar(text,id)}
function previewSourceView(result){const start=iso(new Date());return `<h3>${esc(result.name)}</h3><p>${result.occurrences.length} occurrences in the import window</p><ul>${result.occurrences.filter(e=>e.date>=start).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5).map(e=>`<li>${esc(e.date)} · ${e.allDay?'All day':esc(e.time)} · ${esc(e.title)}</li>`).join('')||'<li>No upcoming events in the next 12 months.</li>'}</ul><p class="tiny">Imported event times are converted to your device timezone.</p>`}
async function refreshCalendars(id){if(window.PLANNER_PUBLIC_DEMO)return;if(calendarBusy)return;const sources=calendarSources().filter(s=>!id||s.id===id).filter(s=>s.type==='link'||s.fileText);if(!sources.length)return;calendarBusy=true;const sessionState=state;const marker=document.getElementById('calendarRefreshStatus');if(marker)marker.textContent='Refreshing calendars…';for(const source of sources){try{const text=source.type==='link'?await fetchCalendarText(source.url):source.fileText;const result=await parseSource(text,source.id);if(state!==sessionState||!calendarSources().includes(source))continue;Object.assign(source,result,{name:source.name,lastSync:new Date().toISOString(),error:''})}catch{if(state===sessionState&&calendarSources().includes(source))source.error='Refresh failed. Your previous events are still available. Check the link or try again.'}}
 calendarBusy=false;if(state===sessionState){save();render()}}
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='calendarConnectForm')return;e.preventDefault();calendarPreview=null;const form=e.target,error=document.getElementById('calendarConnectError'),button=document.getElementById('calendarPreviewButton');button.disabled=true;document.getElementById('calendarConfirmButton').hidden=true;error.textContent='Loading calendar…';try{const url=form.elements.url.value.trim(),file=form.elements.file.files[0];if((!url&&!file)||(url&&file))throw Error('Enter a subscription link OR choose an .ics file.');if(file&&file.size>2*1024*1024)throw Error('Calendar exceeds the 2 MB limit.');if(url&&!/^(https|webcal):\/\//i.test(url))throw Error('Use an HTTPS or webcal subscription link.');const id=crypto.randomUUID(),text=file?await file.text():await fetchCalendarText(url),result=await parseSource(text,id);if(!form.isConnected)return;calendarPreview={...result,id,name:form.elements.name.value.trim()||result.name,type:file?'file':'link',...(file?{fileText:text}:{url}),lastSync:new Date().toISOString()};document.getElementById('calendarPreview').innerHTML=previewSourceView(calendarPreview);document.getElementById('calendarConfirmButton').hidden=false;error.textContent=''}catch(err){if(error.isConnected)error.textContent=err.message}finally{if(button.isConnected)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.closest('#calendarConnectForm')){calendarPreview=null;document.getElementById('calendarConfirmButton').hidden=true}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.calendarConnect)connectCalendar();if(b.dataset.calendarConnectClose){calendarPreview=null;document.getElementById('calendarConnectDialog')?.remove()}if(b.dataset.calendarConfirm&&calendarPreview){state.calendarSources||=[];const duplicate=calendarSources().some(s=>calendarPreview.type==='link'&&s.url===calendarPreview.url);if(duplicate){document.getElementById('calendarConnectError').textContent='This subscription is already connected. Use Refresh now.';return}state.calendarSources.push(calendarPreview);calendarPreview=null;save();document.getElementById('calendarConnectDialog').remove();render()}if(b.dataset.calendarRefresh)refreshCalendars(b.dataset.calendarRefresh);if(b.dataset.calendarDisconnect&&confirm('Disconnect this calendar? Its events will leave your schedule. Past completion records will stay in your planner.')){state.calendarSources=calendarSources().filter(s=>s.id!==b.dataset.calendarDisconnect);save();render()}});
setTimeout(()=>refreshCalendars(),2000);setInterval(()=>{if(!document.hidden)refreshCalendars()},30*60*1000);


document.addEventListener('change',async e=>{if(e.target.getAttribute('id')!=='welcomeBackup')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Backup is too large.');const backup=JSON.parse(await file.text());if(backup.version!==1||!Array.isArray(backup.goals)||!backup.weeklyGoals||!backup.daily||!backup.weeklyStats||!backup.finance)throw Error('Invalid planner backup.');if(!confirm('Import this backup and replace the planner in this browser?'))return;state={...clone(DEFAULT),...backup,onboardingComplete:true};save();document.getElementById('welcomeDialog')?.remove();render();refreshCalendars()}catch(error){alert('Could not import backup: '+error.message)}});
let diaryNotice={date:'',text:''};
function ensureDiaryEntries(){let changed=false;for(const [date,d] of Object.entries(state.daily||{})){if(d.note?.trim()&&!d.legacyNoteMigrated){d.diaryEntries||=[];if(!d.diaryEntries.some(e=>e.id==='legacy_'+date))d.diaryEntries.push({id:'legacy_'+date,text:d.note,createdAt:null,updatedAt:null});d.legacyNoteMigrated=true;changed=true}}return changed}
function diaryTimestamp(value){return value?new Date(value).toLocaleString('en-MY',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Earlier entry · original time unavailable'}
function diaryMarkup(date){const d=state.daily[date]||{},draft=d.diaryDraft||{},entries=d.diaryEntries||[];return `<section class="panel span7 diary-panel"><div class="eyebrow">A MOMENT FOR YOURSELF</div><h2>My diary</h2><p class="tiny">${esc(parseDate(date).toLocaleDateString('en-MY',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</p><form id="diaryForm"><div class="field"><label for="diaryText">${draft.editingId?'Edit your entry':'What’s on your mind?'}</label><textarea id="diaryText" name="text" rows="5" maxlength="20000" required placeholder="Write about your day, a small win, or anything you want to remember…">${esc(draft.text||'')}</textarea></div><div class="row wrap" style="margin-top:12px"><button class="action" type="submit">${draft.editingId?'Save changes':'Save entry'}</button>${draft.editingId?'<button class="action outline" type="button" data-diary-cancel="1">Cancel edit</button>':''}</div></form><p id="diarySaveStatus" role="status" aria-live="polite" class="tiny">${diaryNotice.date===date?esc(diaryNotice.text):'Drafts are kept as you write. Use Save entry to add it to your diary.'}</p><div class="rule"></div><div class="row between wrap"><h3>Saved entries <span class="tiny">(${entries.length})</span></h3><button class="action outline" type="button" data-diary-new="1">Add another entry</button></div><div class="diary-entries">${entries.slice().reverse().map(entry=>`<article class="diary-entry"><div class="row between wrap"><time ${entry.createdAt?'datetime="'+esc(entry.createdAt)+'"':''}>${esc(diaryTimestamp(entry.createdAt))}</time><button type="button" class="action outline" data-diary-edit="${esc(entry.id)}">Edit entry</button></div><p class="diary-entry-text">${esc(entry.text)}</p>${entry.updatedAt?`<small>Edited ${esc(diaryTimestamp(entry.updatedAt))}</small>`:''}</article>`).join('')||'<p class="muted">Your saved entries will appear here. You can add more than one entry each day.</p>'}</div></section>`}
function storeDiaryEntry(date,text,editingId='',now=new Date().toISOString()){const value=text.trim();if(!value)return false;const d=state.daily[date]||(state.daily[date]={checks:{},note:''});d.diaryEntries||=[];if(editingId){const entry=d.diaryEntries.find(e=>e.id===editingId);if(!entry)return false;entry.text=value;entry.updatedAt=now}else d.diaryEntries.push({id:crypto.randomUUID(),text:value,createdAt:now,updatedAt:null});d.diaryDraft={text:'',editingId:''};return true}
function renderDaily(){const date=parseDate(day),d=dstate(),tasks=d.checks||{},complete=habits().filter(x=>tasks[x[0]]).length;document.getElementById('page-daily').innerHTML=heading('THE SMALL STEPS','Daily routine','Your activities, check-ins and saved diary entries.')+`<div class="row between wrap day-toolbar"><h2>${date.toLocaleDateString('en-MY',{weekday:'long',day:'numeric',month:'long'})}</h2><div class="row"><button class="smallbtn" type="button" data-daymove="-1" aria-label="Previous day">‹</button><input id="dayPicker" aria-label="Choose day" type="date" value="${day}"><button class="smallbtn" type="button" data-daymove="1" aria-label="Next day">›</button><button class="action outline" type="button" data-open-day="${iso(new Date())}">Today</button></div></div><div class="grid"><section class="panel span5"><div class="row between wrap"><h2>My daily habits</h2><span class="pill green">${complete}/${habits().length} completed</span></div><div class="list">${habits().map(([id,title,desc])=>`<label class="checkrow ${tasks[id]?'done':''}"><input type="checkbox" data-daily="${esc(id)}" ${tasks[id]?'checked':''}><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></label>`).join('')||'<p class="muted">Add your habits in Settings & backup.</p>'}</div></section>${diaryMarkup(day)}</div>`}
function homeDayPanels(){const today=iso(new Date()),next=parseDate(today);next.setDate(next.getDate()+1);const tomorrow=iso(next);const daily=state.daily[today]?.checks||{};const tasks=[...dayTodos(today).slice().reverse().map(t=>({...t,id:'todo_'+t.id,oneOff:true})),...habits().map(([id,title])=>({id,title,habit:true})),...scheduleEntries(today).filter(e=>!e.skip).map(e=>({...e,id:'schedule_'+e.id,habit:false}))];const tomorrowItems=scheduleEntries(tomorrow).filter(e=>!e.skip);return `<div class="grid home-days"><section class="panel span6"><div class="row between wrap"><div><div class="eyebrow">${esc(parseDate(today).toLocaleDateString('en-MY',{weekday:'long',day:'numeric',month:'short'}))}</div><h2>Today’s tasks</h2></div><span class="pill green">${tasks.filter(t=>daily[t.id]).length}/${tasks.length} completed</span></div>${quickTaskForm()}<div class="list">${tasks.slice(0,12).map(t=>`<label class="checkrow ${daily[t.id]?'done':''}"><input type="checkbox" data-home-task="${esc(t.id)}" ${daily[t.id]?'checked':''}><span><strong>${esc(t.title)}</strong><small>${t.oneOff?'Added for today':t.habit?'Daily habit':t.allDay?'All day':esc(t.time)+(t.end?' – '+esc(t.end):' onward')}</small></span></label>`).join('')||'<p class="muted">No tasks for today yet. Add one above, or choose a habit or scheduled activity.</p>'}</div><button class="action outline" type="button" data-open-day="${today}">Open today${tasks.length>12?' · '+(tasks.length-12)+' more tasks':''} →</button></section><section class="panel span6"><div class="eyebrow">${esc(parseDate(tomorrow).toLocaleDateString('en-MY',{weekday:'long',day:'numeric',month:'short'}))}</div><h2>A peek at tomorrow</h2><div class="list">${tomorrowItems.slice(0,6).map(t=>`<div class="tomorrow-item"><span class="pill">${t.allDay?'All day':esc(t.time)}</span><div><strong>${esc(t.title)}</strong>${t.end?'<small>Until '+esc(t.end)+'</small>':''}</div></div>`).join('')||'<p class="muted">Nothing scheduled tomorrow. A little breathing room.</p>'}</div><button class="action outline" type="button" data-open-day="${tomorrow}">View tomorrow${tomorrowItems.length>6?' · '+(tomorrowItems.length-6)+' more':''} →</button></section></div>`}
function renderHomeDayPanels(){document.querySelector('#page-overview .page-heading').insertAdjacentHTML('afterend',homeDayPanels())}
document.addEventListener('change',e=>{const t=e.target;if(t.id==='profileTheme'){state.profile={...profile(),theme:t.value};applyProfile();save();const status=document.getElementById('profileThemeStatus');if(status)status.textContent='Colour palette saved ✓'}if(t.dataset.homeTask){const today=iso(new Date());const d=state.daily[today]||(state.daily[today]={checks:{},note:''});d.checks||={};d.checks[t.dataset.homeTask]=t.checked;save();render()}});
document.addEventListener('input',e=>{if(e.target.id==='diaryText'){const d=dstate();d.diaryDraft={...(d.diaryDraft||{}),text:e.target.value};save()}});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='diaryForm')return;e.preventDefault();const draft=dstate().diaryDraft||{};if(storeDiaryEntry(day,document.getElementById('diaryText').value,draft.editingId)){diaryNotice={date:day,text:draft.editingId?'Your entry has been updated.':'Entry saved. You can write another entry above.'};save();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openDay){day=b.dataset.openDay;go('daily')}if(b.dataset.diaryEdit){const entry=(dstate().diaryEntries||[]).find(e=>e.id===b.dataset.diaryEdit);if(entry){const draft=dstate().diaryDraft;if(draft?.text?.trim()&&draft.text!==entry.text&&!confirm('Replace your current draft to edit this entry?'))return;dstate().diaryDraft={editingId:entry.id,text:entry.text};save();render();document.getElementById('diaryText')?.focus()}}if(b.dataset.diaryNew){if(dstate().diaryDraft?.editingId){if(dstate().diaryDraft.text?.trim()&&!confirm('Leave this edit and start a new entry?'))return;dstate().diaryDraft={editingId:'',text:''};save();render()}document.getElementById('diaryText')?.focus()}if(b.dataset.diaryCancel){dstate().diaryDraft={editingId:'',text:''};save();render()}});

let reviewMode='month',reviewEditing={},reviewNotice='';
function periodDays(prefix){const year=Number(prefix.slice(0,4));return prefix.length===7?new Date(year,Number(prefix.slice(5,7)),0).getDate():(new Date(year,1,29).getMonth()===1?366:365)}
function reviewPeriod(){return reviewMode==='month'?reviewMonth:String(reviewYear)}
function reviewRecord(){return reviewMode==='month'?(state.monthReviews[reviewMonth]||{}):(state.yearReviews[reviewYear]||{})}
function periodActivity(prefix){const today=iso(new Date());const entries=Object.entries(state.daily||{}).filter(([date])=>date.startsWith(prefix)&&date<=today);const checks=entries.reduce((n,[,d])=>n+Object.values(d.checks||{}).filter(Boolean).length,0);return {days:entries.filter(([,d])=>Object.values(d.checks||{}).some(Boolean)).length,checks,diary:entries.reduce((n,[,d])=>n+(d.diaryEntries||[]).length,0)}}
function reviewCalendar(prefix){const yearly=prefix.length===4;const year=Number(prefix.slice(0,4));if(yearly)return `<div class="activity-months">${Array.from({length:12},(_,i)=>{const period=year+'-'+String(i+1).padStart(2,'0'),s=periodActivity(period),days=new Date(year,i+1,0).getDate();return `<div><strong>${new Date(year,i,1).toLocaleDateString('en-MY',{month:'short'})}</strong><div class="activity-track"><i style="width:${s.days/days*100}%"></i></div><span>${s.days} active days</span></div>`}).join('')}</div>`;const month=Number(prefix.slice(5,7));const count=new Date(year,month,0).getDate();return `<div class="activity-days">${Array.from({length:count},(_,i)=>{const date=prefix+'-'+String(i+1).padStart(2,'0'),active=periodActivity(date).days>0,future=date>iso(new Date());return `<span class="activity-day ${active?'active':''} ${future?'future':''}" title="${date}: ${future?'Upcoming':active?'Activity recorded':'No completed check-ins recorded'}"><b>${i+1}</b><small>${future?'·':active?'✓':'–'}</small></span>`}).join('')}</div><p class="tiny">Highlighted dates have at least one completed habit, task or scheduled activity. Upcoming days are not counted.</p>`}
function renderReviews(){const period=reviewPeriod(),record=reviewRecord(),key=reviewMode+':'+period,draft=state.reviewDrafts?.[key]||record;const stats=periodActivity(period),goals=state.goals.filter(g=>g.due?.startsWith(period)),done=goals.filter(g=>g.done).length,pct=goals.length?Math.round(done/goals.length*100):0;const target=Number(record.activityTarget)||0;const hasReview=record.savedAt||record.focus||record.wins||record.adjust||record.success||record.reflection;const editing=reviewEditing[key]||!hasReview;const year=new Date().getFullYear();const years=[...new Set([year-1,year,year+1,reviewYear,...state.goals.map(g=>Number(g.due?.slice(0,4))).filter(Boolean),...Object.keys(state.yearReviews||{}).map(Number)])].sort((a,b)=>a-b);document.getElementById('page-reviews').innerHTML=heading('SEE YOUR PROGRESS','Progress & reviews','See what you did, work towards a target and save what you learned.')+`<div class="panel review-toolbar"><div class="row between wrap"><div class="row"><button type="button" class="action ${reviewMode==='month'?'':'outline'}" data-review-mode="month" aria-pressed="${reviewMode==='month'}">Monthly</button><button type="button" class="action ${reviewMode==='year'?'':'outline'}" data-review-mode="year" aria-pressed="${reviewMode==='year'}">Yearly</button></div>${reviewMode==='month'?`<label class="row">Month <input id="reviewMonth" type="month" value="${reviewMonth}" aria-label="Choose review month"></label>`:`<label class="row">Year <select id="reviewYear" aria-label="Choose review year">${years.map(y=>`<option ${reviewYear===y?'selected':''}>${y}</option>`).join('')}</select></label>`}</div></div><div class="grid"><div class="panel span6"><h2>Goals due ${reviewMode==='month'?'this month':'this year'}</h2><div class="review-number">${done}<small> / ${goals.length} completed</small></div>${meter(pct)}<p class="tiny">${goals.length?pct+'% completed · Based on target dates, not completion dates.':'No goals with a target date in this period yet.'}</p><div class="list">${goals.map(g=>`<label class="checkrow ${g.done?'done':''}"><input type="checkbox" data-goalcheck="${esc(g.id)}" ${g.done?'checked':''}><span><strong>${esc(g.title)}</strong><small>Target ${esc(g.due)}</small></span></label>`).join('')}</div><form id="periodGoalForm" class="review-goal-form"><label for="periodGoalTitle">Add a goal for ${esc(period)}</label><div class="row wrap"><input id="periodGoalTitle" name="title" required maxlength="160" placeholder="A clear outcome to work towards"><button class="action" type="submit">Add goal</button></div><p class="tiny">Target date defaults to the end of this period. You can edit it in Goals & tasks.</p></form></div><div class="panel span6"><h2>Your recorded activity</h2><div class="three-cols review-stats"><div><strong>${stats.days}</strong><span>Active days</span></div><div><strong>${stats.checks}</strong><span>Completed check-ins</span></div><div><strong>${stats.diary}</strong><span>Diary entries</span></div></div>${target?`<h3>Active-days target</h3><p>${stats.days} of ${target} days · ${Math.min(100,Math.round(stats.days/target*100))}%</p>${meter(stats.days/target*100,'green')}`:'<p class="callout">Set an active-days target in your review below to track consistency towards a goal you choose.</p>'}${reviewCalendar(period)}</div><section class="panel span12"><div class="row between wrap"><h2>${reviewMode==='month'?'Monthly':'Yearly'} reflection</h2>${!editing?'<button class="action outline" type="button" data-review-edit="1">Edit review</button>':''}</div><p id="reviewStatus" role="status" class="tiny">${esc(reviewNotice)}</p>${editing?`<form id="periodReviewForm"><div class="two-cols"><div class="field"><label for="reviewFocus">What mattered most in this period?</label><textarea id="reviewFocus" name="focus" data-review-draft="focus" maxlength="2000">${esc(draft.focus||'')}</textarea></div><div class="field"><label for="reviewTarget">Active-days target (optional)</label><input id="reviewTarget" name="activityTarget" data-review-draft="activityTarget" type="number" min="0" max="${periodDays(period)}" step="1" value="${esc(draft.activityTarget||'')}" placeholder="e.g. 20"><small>A day counts once when you complete at least one habit, task or scheduled session.</small></div><div class="field"><label for="reviewWins">${reviewMode==='month'?'What went well?':'Wins and success criteria'}</label><textarea id="reviewWins" name="wins" data-review-draft="${reviewMode==='month'?'wins':'success'}" maxlength="5000">${esc(reviewMode==='month'?draft.wins||'':draft.success||'')}</textarea></div><div class="field"><label for="reviewAdjust">What did you learn, and what will you change?</label><textarea id="reviewAdjust" name="adjust" data-review-draft="${reviewMode==='month'?'adjust':'reflection'}" maxlength="5000">${esc(reviewMode==='month'?draft.adjust||'':draft.reflection||'')}</textarea></div></div><button type="submit" class="action">Save ${reviewMode==='month'?'monthly':'yearly'} review</button>${hasReview?'<button type="button" class="action outline" data-review-cancel="1">Cancel edit</button>':''}</form>`:`<div class="review-saved two-cols"><div><h3>Main focus</h3><p>${esc(record.focus||'Not recorded')}</p><h3>Active-days target</h3><p>${target?target+' days':'Not set'}</p></div><div><h3>${reviewMode==='month'?'What went well':'Wins and success criteria'}</h3><p>${esc(reviewMode==='month'?record.wins||'Not recorded':record.success||'Not recorded')}</p><h3>Learning & next steps</h3><p>${esc(reviewMode==='month'?record.adjust||'Not recorded':record.reflection||'Not recorded')}</p></div></div><p class="tiny">${record.savedAt?'Saved '+esc(diaryTimestamp(record.savedAt)):'Earlier reflection preserved from your existing planner.'}</p>`}</section></div>`}
function savePeriodReview(values){const period=reviewPeriod(),key=reviewMode+':'+period,previous=reviewRecord();const target=Number(values.activityTarget)||0;if(!Number.isInteger(target)||target<0||target>periodDays(period))throw Error('Choose a whole-number active-days target within this period.');const next={...previous,focus:values.focus.trim(),activityTarget:target,savedAt:new Date().toISOString()};if(reviewMode==='month'){next.wins=values.wins.trim();next.adjust=values.adjust.trim();state.monthReviews[reviewMonth]=next}else{next.success=values.wins.trim();next.reflection=values.adjust.trim();state.yearReviews[reviewYear]=next}if(state.reviewDrafts)delete state.reviewDrafts[key];delete reviewEditing[key];reviewNotice='Review saved. Your answers and progress are available here whenever you return.'}
function compoundProjection(principal,contribution,months,annualRate,frequency=12){const n=Math.max(0,Math.min(1200,Math.floor(Number(months)||0))),p=Math.max(0,Number(principal)||0),payment=Math.max(0,Number(contribution)||0),rate=Math.min(100,Math.max(0,Number(annualRate)||0))/100,m=[1,4,12,365].includes(Number(frequency))?Number(frequency):12;const monthlyRate=Math.expm1(Math.log1p(rate/m)*m/12),factor=monthlyRate?Math.expm1(n*Math.log1p(monthlyRate))/monthlyRate:n,growth=Math.exp(n*Math.log1p(monthlyRate)),deposits=p+payment*n,total=p*growth+payment*factor;return {months:n,monthlyRate,factor,growth,deposits,total,interest:Math.max(0,total-deposits)}}
function savingsMonths(deadline,today=new Date()){if(!/^\d{4}-\d{2}-\d{2}$/.test(deadline))return 0;const end=parseDate(deadline);today=new Date(today.getFullYear(),today.getMonth(),today.getDate());if(end<=today)return 0;return Math.max(0,(end.getFullYear()-today.getFullYear())*12+end.getMonth()-today.getMonth()+(end.getDate()>today.getDate()?1:0))}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const key=reviewMode+':'+reviewPeriod();if(b.dataset.reviewMode){reviewMode=b.dataset.reviewMode;reviewNotice='';render()}if(b.dataset.reviewEdit){reviewEditing[key]=true;render()}if(b.dataset.reviewCancel){if(state.reviewDrafts)delete state.reviewDrafts[key];delete reviewEditing[key];reviewNotice='';save();render()}});
document.addEventListener('input',e=>{if(!e.target.dataset.reviewDraft)return;const key=reviewMode+':'+reviewPeriod();state.reviewDrafts||={};state.reviewDrafts[key]||={...reviewRecord()};state.reviewDrafts[key][e.target.dataset.reviewDraft]=e.target.value;save()});
document.addEventListener('submit',e=>{const id=e.target.getAttribute('id');if(id==='periodReviewForm'){e.preventDefault();try{savePeriodReview(Object.fromEntries(new FormData(e.target)));save();render()}catch(error){document.getElementById('reviewStatus').textContent=error.message}}if(id==='periodGoalForm'){e.preventDefault();const title=new FormData(e.target).get('title').trim();if(!title)return;const period=reviewPeriod(),date=reviewMode==='month'?iso(new Date(Number(period.slice(0,4)),Number(period.slice(5,7)),0)):period+'-12-31';state.goals.push({id:crypto.randomUUID(),title,area:'Personal',due:date,done:false});save();render()}});

function savingsMoney(value){return 'RM '+Number(value||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}
function savingsValues(key,defaultDeadline){const deadline=state.finance[key+'Deadline']||defaultDeadline,goal=Math.max(0,field(key+'Goal')),saved=Math.max(0,field(key+'Saved')),monthly=Math.max(0,field(key+'Monthly')),rate=field(key+'Rate'),frequency=field(key+'Frequency')||12,projection=compoundProjection(saved,monthly,savingsMonths(deadline),rate,frequency),needed=projection.factor?Math.max(0,(goal-saved*projection.growth)/projection.factor):null,hasAmounts=[key+'Saved',key+'Monthly'].some(k=>state.finance[k]!==undefined&&state.finance[k]!==null&&state.finance[k]!==''),pct=goal?Math.min(100,Math.round(saved/goal*100)):0;return {deadline,goal,saved,monthly,rate,frequency,projection,needed,hasAmounts,pct}}
function savingsResults(key,defaultDeadline){const v=savingsValues(key,defaultDeadline),p=v.projection,suggested=v.needed===null?null:Math.ceil(v.needed*100)/100;return `<h3>Actual savings progress</h3>${meter(v.pct,'green')}<div class="savings-results" aria-live="polite"><div><span>Your money contributed</span><strong>${v.hasAmounts?savingsMoney(p.deposits):'—'}</strong></div><div><span>Estimated interest earned</span><strong>${v.hasAmounts?savingsMoney(p.interest):'—'}</strong></div><div class="savings-total"><span>Projected balance at target</span><strong>${v.hasAmounts?savingsMoney(p.total):'—'}</strong></div><div><span>Monthly contribution needed</span><strong>${v.goal?(suggested===null?(v.saved>=v.goal?'Target reached':'Target date reached'):savingsMoney(suggested)):'Set a target'}</strong></div></div>${!v.hasAmounts?'<p class="callout">Enter <b>Already saved</b> or a <b>Monthly contribution</b> to calculate growth. Your target amount is what you want to reach; it is not a deposit.</p>':v.saved===0&&v.monthly===0?'<p class="tiny">With no starting savings or monthly contributions, the projected balance and interest are zero.</p>':v.rate===0?'<p class="tiny">The rate is 0%, so projected interest is zero. Contributions still increase your projected balance.</p>':''}${suggested!==null&&suggested>0?`<button type="button" class="action outline" data-use-savings-plan="${key}">Use suggested ${savingsMoney(suggested)}/month</button><p class="tiny">This fills the monthly contribution field with a planning amount. It does not change your actual savings.</p>`:''}<p class="tiny">${p.months} monthly periods remaining (partial periods rounded up). Contributions are added at the end of each period using equivalent monthly growth for the chosen frequency. Interest is a projection and is not added to your actual saved amount. Excludes fees, taxes and inflation; the assumed rate may change.</p><p class="tiny" role="status" id="${key}SavingsStatus">Results update as you type.</p>`}
function moneyCard(name,key,defaultDeadline){const v=savingsValues(key,defaultDeadline);return `<section class="panel span6" data-savings-card="${key}" data-savings-default="${defaultDeadline}"><div class="row between wrap panel-title"><h2>${esc(name)}</h2><span class="pill green savings-progress-badge">${v.goal?v.pct+'% actually saved':'Set a target'}</span></div><div class="two-cols">${[['Goal','Target amount (RM)'],['Saved','Already saved (RM)'],['Monthly','Monthly contribution (RM)']].map(([suffix,label])=>`<div class="field"><label for="${key+suffix}">${label}</label><input id="${key+suffix}" data-money="${key+suffix}" type="number" min="0" max="1000000000000" step="any" inputmode="decimal" value="${esc(state.finance[key+suffix]??'')}" placeholder="0"></div>`).join('')}<div class="field"><label for="${key}Deadline">Target date</label><input id="${key}Deadline" data-money="${key}Deadline" type="date" value="${esc(v.deadline)}"></div><div class="field"><label for="${key}Rate">Estimated annual interest rate (nominal %)</label><input id="${key}Rate" data-money="${key}Rate" type="number" min="0" max="100" step="any" inputmode="decimal" value="${esc(state.finance[key+'Rate']??'0')}"></div><div class="field"><label for="${key}Frequency">Compounding frequency</label><select id="${key}Frequency" data-money="${key}Frequency">${[[1,'Annually'],[4,'Quarterly'],[12,'Monthly'],[365,'Daily']].map(([value,label])=>`<option value="${value}" ${v.frequency===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="savings-live">${savingsResults(key,defaultDeadline)}</div></section>`}
function refreshSavingsResults(card){const key=card.dataset.savingsCard,deadline=card.dataset.savingsDefault,v=savingsValues(key,deadline);card.querySelector('.savings-live').innerHTML=savingsResults(key,deadline);card.querySelector('.savings-progress-badge').textContent=v.goal?v.pct+'% actually saved':'Set a target'}
function updateSavingsInput(input){const card=input.closest('[data-savings-card]');if(!card)return;if(!input.checkValidity()){const status=document.getElementById(card.dataset.savingsCard+'SavingsStatus');if(status)status.textContent=input.validationMessage;return}state.finance[input.dataset.money]=input.value;save();refreshSavingsResults(card)}
document.addEventListener('input',e=>{if(e.target.dataset.money)updateSavingsInput(e.target)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-use-savings-plan]');if(!b)return;const card=b.closest('[data-savings-card]'),key=b.dataset.useSavingsPlan,v=savingsValues(key,card.dataset.savingsDefault);if(v.needed===null)return;const monthly=Math.ceil(v.needed*100)/100;state.finance[key+'Monthly']=String(monthly);const input=document.getElementById(key+'Monthly');input.value=String(monthly);save();refreshSavingsResults(card)});

let todayTaskMessage='';
function dayTodos(date){return state.daily[date]?.todos||[]}
function addDayTodo(date,title){const clean=String(title||'').trim();if(!clean)return null;const d=state.daily[date]||(state.daily[date]={checks:{},note:''});d.todos||=[];d.checks||={};const task={id:crypto.randomUUID(),title:clean.slice(0,160),createdAt:new Date().toISOString()};d.todos.push(task);d.checks['todo_'+task.id]=false;return task}
function quickTaskForm(){return `<form id="homeTodoForm" class="quick-task-form"><label for="homeTodoTitle">Add a task for today</label><div class="row"><input id="homeTodoTitle" name="title" required maxlength="160" placeholder="e.g. Send an application or buy groceries" autocomplete="off"><button class="action" type="submit">+ Add</button></div><p class="tiny" id="todayTaskStatus" role="status">${esc(todayTaskMessage||'Saved for today and shown in Daily routine.')}</p></form>`}
function renderDayTodos(){const d=state.daily[day]||{},tasks=dayTodos(day);document.querySelector('#page-daily .day-toolbar').insertAdjacentHTML('afterend',`<section class="panel day-todos"><div class="row between wrap"><h2>My tasks for this day</h2><span class="pill green">${tasks.filter(t=>d.checks?.['todo_'+t.id]).length}/${tasks.length} completed</span></div><div class="list">${tasks.map(task=>`<label class="checkrow ${d.checks?.['todo_'+task.id]?'done':''}"><input type="checkbox" data-daily="todo_${esc(task.id)}" ${d.checks?.['todo_'+task.id]?'checked':''}><span><strong>${esc(task.title)}</strong><small>Task added for ${day}</small></span></label>`).join('')||'<p class="muted">No extra tasks added for this date.</p>'}</div></section>`)}
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='homeTodoForm')return;e.preventDefault();const title=new FormData(e.target).get('title');if(!addDayTodo(iso(new Date()),title))return;todayTaskMessage='Task added to today’s list.';save();render();document.getElementById('homeTodoTitle')?.focus()});

function openPublicSample(){if(!window.PLANNER_PUBLIC_DEMO)return;const now=new Date(),today=iso(now),year=now.getFullYear(),monthEnd=iso(new Date(year,now.getMonth()+1,0)),end=iso(new Date(year,now.getMonth()+3,0));state=clone(DEFAULT);Object.assign(state,{onboardingComplete:true,profile:{name:'Demo',theme:'sage',intention:'Small steps, steady progress.'},plan:{main:'Make time for learning and wellbeing',monthly:'Finish a personal project',yearly:'Build a consistent learning routine',rhythm:'Gentle and flexible'},habits:[['sample_read','Read 10 pages','A little each day'],['sample_move','Move for 20 minutes','Make space for yourself']],weeklyItems:[['sample_read','Reading sessions','Time for a good book'],['sample_move','Movement sessions','A walk or activity you enjoy']],weeklyGoals:{sample_read:5,sample_move:4},goals:[{id:'sample_goal1',title:'Finish a personal project',area:'Personal',due:monthEnd,done:false},{id:'sample_goal2',title:'Finish one book',area:'Personal',due:monthEnd,done:true},{id:'sample_goal3',title:'Build a consistent learning routine',area:'Education',due:year+'-12-31',done:false}],schedule:[{id:'sample_class',title:'Learning session',days:[1,2,3,4,5],time:'09:00',end:'10:00',from:iso(new Date(year,now.getMonth(),1)),until:end},{id:'sample_walk',title:'Evening walk',days:[0,1,2,3,4,5,6],time:'17:30',end:'18:00',from:iso(new Date(year,now.getMonth(),1)),until:end}],finance:{weddingGoal:'5000',weddingSaved:'1000',weddingMonthly:'150',weddingRate:'3.5',weddingFrequency:'12',weddingDeadline:iso(new Date(year+1,now.getMonth(),now.getDate()))},monthReviews:{[today.slice(0,7)]:{focus:'Make room for learning',wins:'Small sessions helped me stay consistent.',adjust:'Plan fewer tasks and finish them.',activityTarget:20,savedAt:new Date().toISOString()}}});
for(let i=0;i<7;i++){const d=new Date(now);d.setDate(d.getDate()-i);const date=iso(d);state.daily[date]={checks:{sample_read:i!==2,sample_move:i%2===0},note:''}}state.daily[today].todos=[{id:'sample_task',title:'Plan the next learning session',createdAt:new Date().toISOString()}];state.daily[today].diaryEntries=[{id:'sample_diary',text:'A small focused session made a good start to the day. This is fictional sample content.',createdAt:new Date().toISOString(),updatedAt:null}];state.weeklyStats[thisWeek()]={sample_read:4,sample_move:2};document.getElementById('welcomeDialog')?.remove();save();page='overview';history.replaceState(null,'',location.pathname+'#overview');render()}
document.addEventListener('click',e=>{if(e.target.closest('[data-public-sample]'))openPublicSample()});

boot();})();
